import java.util.ArrayList;
import java.util.List;

public class Main {
  public static void main(String[] args) {
    int[] arr = {1, 2, 3, 4, 5, 4, 4};
    List<Integer> x = new ArrayList<>();

    for(int i = 0; i < arr.length; i++) {
        if (arr[i] == 4) x.add(i);
    }
    System.out.println(x);
  }
}

